import torch
import torch.nn as nn

torch.manual_seed(7)
class SelectiveStateBlock(nn.Module):
    """Small educational Mamba-style selective state-space block."""
    def __init__(self,d):
        super().__init__(); self.inp=nn.Linear(d,d); self.gate=nn.Linear(d,d); self.state=nn.Linear(d,d,bias=False)
    def forward(self,x):
        h=torch.zeros(x.size(0),x.size(2)); outputs=[]
        for t in range(x.size(1)):
            u=torch.tanh(self.inp(x[:,t])); g=torch.sigmoid(self.gate(x[:,t]))
            h=g*u+(1-g)*torch.tanh(self.state(h)); outputs.append(h)
        return torch.stack(outputs,dim=1)
class MambaStyleClassifier(nn.Module):
    def __init__(self):
        super().__init__(); self.block=SelectiveStateBlock(8); self.head=nn.Linear(8,3)
